package cn.zaozhi;

import cn.zaozhi.tool.*;
import cn.zaozhi.agent.*;
import cn.zaozhi.workspace.MaintenanceService;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.nio.file.attribute.FileTime;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class V11MaintenanceTest {
    @TempDir Path dir;
    ToolContext ctx()throws Exception{var s=new Settings(Map.of("DATA_DIR",dir.resolve("data").toString()));var db=new Database(s);var p=Profile.validate(Json.object("nickname","maintenance"));var u=db.createUser(p);String rid=db.claim(u.path("id").asText(),p,"demo","manual",null);db.execute("UPDATE runs SET status='running',started_at=? WHERE id=?",Database.now(),rid);return new ToolContext(rid,u.path("id").asText(),p,db,s);}
    @Test void backupRestoreChecksObjectsAndMaintainsSubscriptionIsolation()throws Exception{var c=ctx();var tools=new ToolRegistry(new NewsClient());tools.execute("search_news",Json.object("query","AI"),c);tools.execute("fetch_article",Json.object("source_id","demo-agent"),c);c.db.event(c.runId,"tool",Json.object("name","fixture","content","x".repeat(5000)));var service=new MaintenanceService(c.db);Path snapshot=dir.resolve("backup"),restored=dir.resolve("restored");service.backup(snapshot);MaintenanceService.restore(snapshot,restored);Database copy=new Database(restored);assertEquals(3,copy.all("SELECT * FROM run_sources").size());assertThrows(cn.zaozhi.controller.ApiException.class,()->copy.events("other",c.runId));assertTrue(Files.exists(restored.resolve("workspaces").resolve(c.runId).resolve("articles/demo-agent.txt")));Files.writeString(snapshot.resolve("artifacts").resolve(c.db.one("SELECT payload_ref FROM events WHERE payload_state='EXTERNAL'").path("payload_ref").asText()),"tampered");assertThrows(IllegalStateException.class,()->MaintenanceService.restore(snapshot,dir.resolve("bad-restore")));}
    @Test void retentionExpiresDetailsAndBodyButPreservesBriefRunShellAndActiveWorkspace()throws Exception{var c=ctx();var tools=new ToolRegistry(new NewsClient());tools.execute("search_news",Json.object("query","AI"),c);tools.execute("fetch_article",Json.object("source_id","demo-agent"),c);c.db.event(c.runId,"tool",Json.object("name","fixture","content","x".repeat(5000)));var result=new AgentRunner(new DemoClient(c.profile),tools).run(c);String bid=c.db.finish(c.runId,result);String old=Instant.now().minus(Duration.ofDays(40)).toString();c.db.execute("UPDATE runs SET finished_at=? WHERE id=?",old,c.runId);c.db.execute("UPDATE events SET created_at=? WHERE run_id=?",old,c.runId);String active=c.db.claim(c.userId,c.profile,"demo","manual",null);new ToolContext(active,c.userId,c.profile,c.db,c.settings);new MaintenanceService(c.db).cleanup(Instant.now());assertFalse(Files.exists(c.db.dataDir.resolve("workspaces").resolve(c.runId)));assertTrue(Files.exists(c.db.dataDir.resolve("workspaces").resolve(active)));assertEquals("EXPIRED",c.db.one("SELECT body_state FROM run_sources WHERE run_id=? AND source_id='demo-agent'",c.runId).path("body_state").asText());assertNotNull(c.db.brief(c.userId,bid));assertNotNull(c.db.one("SELECT id FROM runs WHERE id=?",c.runId));assertEquals("EXPIRED",c.db.one("SELECT payload_state FROM events WHERE run_id=? ORDER BY id LIMIT 1",c.runId).path("payload_state").asText());}
    @Test void orphanGraceAndRetryAncestorRetention()throws Exception{var c=ctx();Path orphan=c.db.dataDir.resolve("artifacts/orphan.json"),recent=c.db.dataDir.resolve("artifacts/recent.json");Files.createDirectories(orphan.getParent());Files.writeString(orphan,"{}");Files.writeString(recent,"{}");Files.setLastModifiedTime(orphan,FileTime.from(Instant.now().minus(Duration.ofHours(25))));String old=Instant.now().minus(Duration.ofDays(100)).toString();c.db.execute("UPDATE runs SET status='failed',finished_at=? WHERE id=?",old,c.runId);var child=c.db.claim(c.userId,"demo","retry",null,null,null,c.runId,c.settings);new MaintenanceService(c.db).cleanup(Instant.now());assertFalse(Files.exists(orphan));assertTrue(Files.exists(recent));assertNotNull(c.db.one("SELECT id FROM runs WHERE id=?",c.runId));assertNotNull(c.db.one("SELECT id FROM runs WHERE id=?",child.id()));}
    @Test void dstMissingTimeMovesForwardAndRepeatedTimeUsesFirstInstant(){var spring=Profile.validate(Json.object("nickname","dst","timezone","America/New_York","time","02:30"));assertNull(Profile.dueDate(spring,Instant.parse("2026-03-08T07:29:59Z")));assertEquals("2026-03-08",Profile.dueDate(spring,Instant.parse("2026-03-08T07:30:00Z")));var fall=Profile.validate(Json.object("nickname","dst","timezone","America/New_York","time","01:30"));assertEquals("2026-11-01",Profile.dueDate(fall,Instant.parse("2026-11-01T05:30:00Z")));assertEquals("2026-11-01",Profile.dueDate(fall,Instant.parse("2026-11-01T06:00:00Z")));}
    @Test void expiredOrCancelledRunCannotCommitEvenWithCandidate()throws Exception{var c=ctx();c.db.execute("UPDATE runs SET deadline_at_ms=0 WHERE id=?",c.runId);assertThrows(IllegalStateException.class,()->c.db.finish(c.runId,Json.object("title","X","intro","Y","items",List.of())));c.db.execute("UPDATE runs SET status='cancelled' WHERE id=?",c.runId);assertThrows(IllegalStateException.class,()->c.db.finish(c.runId,Json.object("title","X","intro","Y","items",List.of())));assertTrue(c.db.all("SELECT * FROM briefs").isEmpty());}
    @Test void subscriptionDeletionRejectsActiveThenRemovesRetryChainWithoutAffectingOthers()throws Exception{var c=ctx();var service=new MaintenanceService(c.db);var other=c.db.createUser(Profile.validate(Json.object("nickname","other")));assertThrows(cn.zaozhi.controller.ApiException.class,()->service.deleteSubscription(c.userId));assertNotNull(c.db.one("SELECT id FROM subscriptions WHERE id=?",c.userId));c.db.execute("UPDATE runs SET status='failed',finished_at=? WHERE id=?",Database.now(),c.runId);String child=c.db.claim(c.userId,"demo","retry",null,null,null,c.runId,c.settings).id();c.db.execute("UPDATE runs SET status='cancelled',finished_at=? WHERE id=?",Database.now(),child);service.deleteSubscription(c.userId);assertNull(c.db.one("SELECT id FROM subscriptions WHERE id=?",c.userId));assertTrue(c.db.all("SELECT id FROM runs WHERE subscription_id=?",c.userId).isEmpty());assertNotNull(c.db.one("SELECT id FROM subscriptions WHERE id=?",other.path("id").asText()));assertFalse(Files.exists(c.db.dataDir.resolve("workspaces").resolve(c.runId)));assertTrue(c.db.all("PRAGMA foreign_key_check").isEmpty());}
    @Test void integritySweepMarksMissingObjectsAndSequenceSurvivesPartialPruning()throws Exception{var c=ctx();c.db.event(c.runId,"tool",Json.object("content","a".repeat(5000)));c.db.event(c.runId,"tool",Json.object("message","second"));c.db.execute("DELETE FROM events WHERE run_id=? AND seq=1",c.runId);c.db.event(c.runId,"tool",Json.object("content","b".repeat(5000)));assertEquals(3,c.db.one("SELECT MAX(seq) n FROM events WHERE run_id=?",c.runId).path("n").asInt());var e=c.db.one("SELECT payload_ref FROM events WHERE run_id=? AND seq=3",c.runId);Files.delete(c.db.dataDir.resolve("artifacts").resolve(e.path("payload_ref").asText()));new MaintenanceService(c.db).cleanup(Instant.now());assertEquals("MISSING",c.db.one("SELECT payload_state FROM events WHERE run_id=? AND seq=3",c.runId).path("payload_state").asText());}
}

